import json
E = '_'  # empty square marker
OUT = []
def add(p, r): OUT.append([p, r])

def sq(i): return 'abcdefgh'[i % 8] + str(8 - i // 8)
def rc(i): return i // 8, i % 8
def idx(r, c): return r * 8 + c
def onb(r, c): return 0 <= r < 8 and 0 <= c < 8

# ---- parse input ----
add(r'^(\S+) w (\S+) (\S+) \d+ \d+\s*$', r'P:\1 \2 \3')
for d in range(8, 0, -1):
    add(str(d) + r'(?=\S* )', E * d)
add(r'/(?=\S* )', '')

def board_pat(cond):
    """cond: {idx: regex class}. returns pattern with every square group-captured,
    and mapping idx-> group number for conditioned squares / gaps."""
    pat = ''
    groups = []  # list of (start, length)
    pos = 0
    for i in sorted(cond):
        if i > pos:
            pat += '(.{%d})' % (i - pos); groups.append((pos, i - pos))
        pat += '(' + cond[i] + ')'; groups.append((i, 1))
        pos = i + 1
    if pos < 64:
        pat += '(.{%d})' % (64 - pos); groups.append((pos, 64 - pos))
    return pat, groups

def board_repl(groups, repl):
    out = ''
    for g, (s, l) in enumerate(groups, 1):
        if l == 1 and s in repl:
            out += repl[s]
        else:
            out += r'\g<%d>' % g
    return out, len(groups)

def gen_move(cond, repl, tag='M', castle_pat=r'(\S+)', ep_match=r'\S+', newep='-'):
    bp, groups = board_pat(cond)
    br, n = board_repl(groups, repl)
    pat = r'(?m)^P:' + bp + ' ' + castle_pat + ' ' + ep_match + '$'
    rep = r'\g<0>' + '\n' + tag + ':' + br + ' ' + r'\g<%d>' % (n + 1) + ' ' + newep
    add(pat, rep)

TGT = '[a-z_]'
BLK = '[a-z]'
KN = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
KG = [(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]
ORTH = [(1,0),(-1,0),(0,1),(0,-1)]
DIAG = [(1,1),(1,-1),(-1,1),(-1,-1)]

for s in range(64):
    r, c = rc(s)
    # knights & king
    for P, offs in (('N', KN), ('K', KG)):
        for dr, dc in offs:
            if onb(r+dr, c+dc):
                t = idx(r+dr, c+dc)
                gen_move({s: P, t: TGT}, {s: E, t: P})
    # sliders
    for P, dirs in (('R', ORTH), ('B', DIAG), ('Q', ORTH + DIAG)):
        for dr, dc in dirs:
            path = []
            rr, cc = r+dr, c+dc
            while onb(rr, cc):
                t = idx(rr, cc)
                cond = {s: P, t: TGT}
                for m in path: cond[m] = E
                gen_move(cond, {s: E, t: P})
                path.append(t)
                rr += dr; cc += dc
    # pawns
    if 1 <= r <= 6:
        t = s - 8
        promo = 'Q' if r - 1 == 0 else 'P'
        gen_move({s: 'P', t: E}, {s: E, t: promo})
        if r == 6:
            gen_move({s: 'P', t: E, s - 16: E}, {s: E, s - 16: 'P'}, newep=sq(t))
        for dc in (-1, 1):
            if onb(r-1, c+dc):
                t = idx(r-1, c+dc)
                gen_move({s: 'P', t: BLK}, {s: E, t: promo})
        if r == 3:
            for dc in (-1, 1):
                if onb(r-1, c+dc):
                    t = idx(r-1, c+dc); cap = idx(r, c+dc)
                    gen_move({s: 'P', t: E, cap: 'p'}, {s: E, t: 'P', cap: E}, ep_match=sq(t))
# castling
gen_move({60: 'K', 61: E, 62: E, 63: 'R'}, {60: E, 61: 'R', 62: 'K', 63: E}, tag='O', castle_pat=r'(\S*K\S*)')
gen_move({56: 'R', 57: E, 58: E, 59: E, 60: 'K'}, {56: E, 58: 'K', 59: 'R', 60: E}, tag='o', castle_pat=r'(\S*Q\S*)')

# ---- attack detection ----
def seq(cond):
    pat = ''; pos = 0
    for i in sorted(cond):
        if i > pos: pat += '.{%d}' % (i - pos)
        pat += cond[i]; pos = i + 1
    return pat

def attackers(s):
    r, c = rc(s); alts = []
    for dr, dc in KN:
        if onb(r+dr, c+dc): alts.append(seq({idx(r+dr, c+dc): 'n'}))
    for dr, dc in KG:
        if onb(r+dr, c+dc): alts.append(seq({idx(r+dr, c+dc): 'k'}))
    for dc in (-1, 1):
        if onb(r-1, c+dc): alts.append(seq({idx(r-1, c+dc): 'p'}))
    for dirs, cls in ((ORTH, '[rq]'), (DIAG, '[bq]')):
        for dr, dc in dirs:
            path = []; rr, cc = r+dr, c+dc
            while onb(rr, cc):
                t = idx(rr, cc)
                cond = {t: cls}
                for m in path: cond[m] = E
                alts.append(seq(cond))
                path.append(t); rr += dr; cc += dc
    return '(?=' + '|'.join(alts) + ')'

for tag, squares in (('O', (60, 61)), ('o', (60, 59))):
    for s in squares:
        add(r'(?m)^' + tag + ':' + attackers(s) + r'[^\n]*\n?', '')
add(r'(?m)^[Oo]:', 'M:')
for s in range(64):
    add(r'(?m)^M:(?=.{%d}K)' % s + attackers(s) + r'[^\n]*\n?', '')

# ---- castling rights ----
for need, ch in ((60, 'K'), (63, 'R')):
    add(r'(?m)^(M:(?!.{%d}%s).{64} \S*?)K' % (need, ch), r'\1')
for need, ch in ((60, 'K'), (56, 'R')):
    add(r'(?m)^(M:(?!.{%d}%s).{64} \S*?)Q' % (need, ch), r'\1')
add(r'(?m)^(M:(?!.{7}r).{64} \S*?)k', r'\1')
add(r'(?m)^(M:(?!r).{64} \S*?)q', r'\1')
add(r'(?m)^(M:.{64})  ', r'\1 - ')

# ---- output ----
add(r'(?m)^P:[^\n]*\n?', '')
add(r'(?m)^M:' + '(.{8})' * 8 + r' (\S+) (\S+)$',
    '/'.join(r'\g<%d>' % i for i in range(1, 9)) + r' b \g<9> \g<10> 0 0')
for d in range(8, 0, -1):
    add(E * d, str(d))
add(r'\n+\Z', '')
add(r'\A\n+', '')

json.dump(OUT, open('/tmp/obench-cell-39o4zpsa/bench_opencode_regex-chess___45gkim/re.json', 'w'))
print(len(OUT))
